package io.github.floatmemo.android;
import org.junit.*;
import org.json.*;
import java.util.*;
import static org.junit.Assert.*;
public class TaskPresentationTest {
 private Note note(String raw){Note n=new Note();n.content=raw;return n;}
 @Test public void oldJsonDefaultsToOrdinaryNoteWithoutAlarms(){Note n=Note.fromJson(new JSONObject().put("id","old").put("content","旧笔记"));assertFalse(n.task);assertEquals(0,n.reminderAt);assertTrue(n.formats.isEmpty());assertTrue(n.checks.isEmpty());}
 @Test public void stylesTaskAndChecklistSurviveJsonRoundTrip()throws Exception{Note n=note("- [ ] 买水\n要带文件");n.task=true;n.dueAt=999999;n.reminderAt=888888;n.formats=TextFormat.set(n.formats,6,8,"bold",1);n.checks.put(0,true);Note restored=Note.fromJson(new JSONObject(n.toJson().toString()));assertEquals(n.content,restored.content);assertEquals(1,restored.formats.size());assertEquals(Boolean.TRUE,restored.checks.get(0));assertEquals(n.dueAt,restored.dueAt);assertTrue(restored.task);}
 @Test public void noteCopyDoesNotShareMutableStylesOrChecks(){Note n=note("- [ ] a");n.formats=TextFormat.set(n.formats,6,7,"bold",1);n.checks.put(0,true);Note c=n.copy();c.formats.clear();c.checks.clear();assertEquals(1,n.formats.size());assertEquals(1,n.checks.size());}
 @Test public void presentationAndTaskStateDoNotInvalidateAiSource()throws Exception{Note n=note("- [ ] 记得带文件");n.aiJson="{\"points\":[{\"quote\":\"记得带文件\"}]}";n.aiSourceHash=NoteBodyParser.fingerprint(n);n.formats=TextFormat.set(n.formats,6,11,"size",1.5);n.checks.put(0,true);n.task=true;n.completedAt=12;assertTrue(AiDocument.current(n));}
 @Test public void clearingSelectedBoldPreservesOutsideSelection(){Note n=note("abcdefghij");n.formats=TextFormat.set(n.formats,0,10,"bold",1);n.formats=TextFormat.set(n.formats,3,7,"bold",0);assertEquals(2,n.formats.size());assertEquals(3,n.formats.get(0).end);assertEquals(7,n.formats.get(1).start);}
 @Test public void changingSizeDoesNotRemoveBold(){Note n=note("abcde");n.formats=TextFormat.set(n.formats,0,5,"bold",1);n.formats=TextFormat.set(n.formats,1,4,"size",1.5);n.formats=TextFormat.set(n.formats,2,3,"size",0);assertEquals(3,n.formats.size());assertEquals(1,n.formats.stream().filter(x->x.kind.equals("bold")).count());}
 @Test public void insertingBeforeStyledTextMovesRange(){Note n=note("abcd");n.formats=TextFormat.set(n.formats,1,3,"bold",1);n.content="XXabcd";TextFormat.rebase(n,"abcd");assertEquals(3,n.formats.get(0).start);assertEquals(5,n.formats.get(0).end);}
 @Test public void typingInsideStyledTextKeepsItsStyle(){Note n=note("abcd");n.formats=TextFormat.set(n.formats,1,3,"bold",1);n.content="abXXcd";TextFormat.rebase(n,"abcd");assertEquals(1,n.formats.get(0).start);assertEquals(5,n.formats.get(0).end);}
 @Test public void deletingAllStyledTextRemovesEmptyRange(){Note n=note("abc");n.formats=TextFormat.set(n.formats,1,2,"bold",1);n.content="ac";TextFormat.rebase(n,"abc");assertTrue(n.formats.isEmpty());}
 @Test public void emojiBoundariesRemainValidAfterReplacement(){Note n=note("😀abc");n.formats=TextFormat.set(n.formats,2,5,"size",1.25);n.content="😃abc";TextFormat.rebase(n,"😀abc");TextFormat.validate(n);assertEquals(2,n.formats.get(0).start);}
 @Test(expected=IllegalArgumentException.class) public void invalidSurrogateBoundaryIsRejected(){Note n=note("😀abc");n.formats.add(new TextFormat.Range(1,3,"bold",1));TextFormat.validate(n);}
 @Test public void checkStateMovesWithUnchangedLine(){Note n=note("- [ ] 买水\n- [ ] 拿钥匙");n.checks.put(0,true);n.content="提示\n"+n.content;TextFormat.rebase(n,"- [ ] 买水\n- [ ] 拿钥匙");assertEquals(Boolean.TRUE,n.checks.get(3));}
 @Test public void editedChecklistTextResetsOnlyThatItemsState(){String before="- [ ] 买水\n- [ ] 拿钥匙";Note n=note(before);int second=before.indexOf('\n')+1;n.checks.put(0,true);n.checks.put(second,true);n.content=before.replace("买水","买茶");TextFormat.rebase(n,before);assertFalse(n.checks.containsKey(0));assertEquals(Boolean.TRUE,n.checks.get(second));}
 @Test public void joiningLinesCannotKeepCompletedStateOnChangedTask(){Note n=note("- [ ] a\nmore");n.checks.put(0,true);n.content="- [ ] amore";TextFormat.rebase(n,"- [ ] a\nmore");assertTrue(n.checks.isEmpty());}
 @Test public void codeFenceContentsAreNotInteractiveChecklistItems(){String raw="```\n- [ ] code\n```\n- [ ] task";assertEquals(1,TextFormat.items(raw).size());assertEquals(raw.lastIndexOf("- [ ]"),TextFormat.items(raw).get(0).start);}
 @Test public void explicitFalseCanOverrideAnImportedCheckedMarker(){Note n=note("- [x] done");TextFormat.Item i=TextFormat.items(n.content).get(0);assertTrue(TextFormat.checked(n,i));n.checks.put(0,false);assertFalse(TextFormat.checked(n,i));}
 @Test public void enterContinuesNumberedList(){ListEditing.Edit e=ListEditing.newline("9. 买水\n",5);assertNotNull(e);assertEquals("10. ",e.text);}
 @Test public void enterContinuesUncheckedEvenAfterCheckedMarker(){String raw="- [x] 买水\n";assertEquals("- [ ] ",ListEditing.newline(raw,raw.length()-1).text);}
 @Test public void enterOnEmptyItemExitsList(){String raw="1. \n";ListEditing.Edit e=ListEditing.newline(raw,3);assertEquals(0,e.start);assertEquals(4,e.end);assertEquals("",e.text);}
 @Test public void ordinaryParagraphDoesNotContinueList(){assertNull(ListEditing.newline("普通文字\n",4));}
 @Test public void multilineNumberingIncrementsEachSelectedLine(){assertEquals("1. 买水\n2. 拿钥匙\n3. 出门",ListEditing.prefixLines("买水\n拿钥匙\n出门","1. "));}
 @Test public void multilineChecklistStartsEachItemUnchecked(){assertEquals("- [ ] 买水\n- [ ] 拿钥匙",ListEditing.prefixLines("买水\n拿钥匙","- [ ] "));}
 @Test public void aiReviewStatusDoesNotCompleteTask(){Note n=new Note();n.task=true;n.reviewed=true;n.aiStatus="已确认";assertFalse(NoteTasks.done(n));assertTrue(NoteTasks.matches(n,1));}
 @Test public void completedNoteCannotFloatOrRemindButCanBeFiltered(){Note n=new Note();n.task=true;n.completedAt=100;n.reminderAt=500;n.dueAt=1000;assertFalse(NoteTasks.canFloat(n));assertEquals(0,NoteTasks.nextAlarm(n,NoteTasks.ReminderStage.BEFORE,200));assertTrue(NoteTasks.matches(n,2));}
 @Test public void staleOrEarlyAlarmDoesNotDeliver(){Note n=new Note();n.task=true;n.dueAt=3000;n.reminderAt=2000;n.reminderGeneration=5;assertFalse(NoteTasks.mayDeliver(n,NoteTasks.ReminderStage.BEFORE,4,2200));assertFalse(NoteTasks.mayDeliver(n,NoteTasks.ReminderStage.BEFORE,5,1999));assertTrue(NoteTasks.mayDeliver(n,NoteTasks.ReminderStage.BEFORE,5,2000));}
 @Test public void sentOrTrashedTaskCannotDeliverAgain(){Note n=new Note();n.task=true;n.dueAt=3000;n.reminderAt=1000;n.reminderFiredAt=1200;assertFalse(NoteTasks.mayDeliver(n,NoteTasks.ReminderStage.BEFORE,0,2000));n.reminderFiredAt=0;n.deletedAt=1300;assertFalse(NoteTasks.mayDeliver(n,NoteTasks.ReminderStage.BEFORE,0,2000));assertFalse(ResultGate.accept(n,n.copy()));}
 @Test public void missedButNotYetDueReminderIsRescheduledAndExpiredOneIsNot(){Note n=new Note();n.task=true;n.reminderAt=1000;n.dueAt=10000;assertEquals(5000,NoteTasks.nextAlarm(n,NoteTasks.ReminderStage.BEFORE,2000));assertEquals(0,NoteTasks.nextAlarm(n,NoteTasks.ReminderStage.BEFORE,10001));}
 @Test public void ordinaryNotesAreNotOverdueAndCompletedOnesSortLast(){Note normal=new Note(),done=new Note(),todo=new Note();normal.dueAt=1;done.task=true;done.completedAt=1;done.updatedAt=999;todo.task=true;todo.updatedAt=100;assertFalse(NoteTasks.overdue(normal,200));List<Note> list=new ArrayList<>(Arrays.asList(done,normal,todo));list.sort(NoteTasks.order());assertSame(done,list.get(2));}
 @Test public void importingBackupDisarmsNotificationsUntilExplicitlyReenabled(){Note n=new Note();n.task=true;n.dueAt=99999;n.reminderAt=50000;n.reminderGeneration=3;NoteTasks.resetImportedReminder(n);assertEquals(99999,n.dueAt);assertEquals(0,n.reminderAt);assertEquals(4,n.reminderGeneration);}
 @Test public void importConflictSignatureIncludesTaskFormatAndTrash()throws Exception{Note n=note("abc");String old=ImportPolicy.signature(n);n.task=true;assertNotEquals(old,ImportPolicy.signature(n));n.task=false;n.formats=TextFormat.set(n.formats,0,2,"bold",1);assertNotEquals(old,ImportPolicy.signature(n));n.formats.clear();n.deletedAt=1;assertNotEquals(old,ImportPolicy.signature(n));}
}
